"""Wraps a handler so requests over the limit get 429 Too Many Requests."""

from ratelimit.bucket import TokenBucket


def limit(handler, capacity=10, rate=1.0, clock=None):
    kwargs = {"clock": clock} if clock else {}
    buckets = {}

    def limited(request):
        # Requests without an X-Api-Key header all share the None bucket.
        key = request["headers"].get("X-Api-Key")
        if key not in buckets:
            buckets[key] = TokenBucket(capacity, rate, **kwargs)
        bucket = buckets[key]
        if not bucket.allow():
            retry = str(int(bucket.retry_after()))
            return {"status": 429, "headers": {"Retry-After": retry}, "body": "too many requests"}
        return handler(request)

    return limited
